@AutoConfiguration
@ConditionalOnClass(name = "com.alibaba.csp.sentinel.adapter.gateway.sc.SentinelGatewayFilter")
@ConditionalOnProperty(name = "maritime.gateway.sentinel.enabled", havingValue = "true")
